let notices=[],batchSelection=null,uploadReceipts=new Map();
function notify(message,severity="INFO",page=null,id=null){
  severity=severity.toUpperCase();if(!["SUCCESS","INFO","WARNING","ERROR","ACTION_REQUIRED"].includes(severity))severity="INFO";
  const presentation=FinTrustDisplay.notice(message,severity,page);notices.unshift({id:crypto.randomUUID(),message,severity,page,object:id,...presentation,time:new Date().toISOString(),acknowledged:false});
}
function button(text,fn){const b=node("button",text);b.type="button";b.onclick=fn;return b;}
function heading(panel,title){panel.append(node("h3",title));}
function facts(data){const dl=node("dl","");dl.className="detail";for(const [k,v]of Object.entries(data)){dl.append(node("dt",k.replaceAll("_"," ")),node("dd",FinTrustDisplay.uuid(v)?v:FinTrustDisplay.value(k,v)));}return dl;}
