function showInsights(data){const panel=node("div","");panel.append(node("p",data.scope+". Risk charts include scored accepted entries only; cross-border is a risk factor, not a fraud verdict."));const grid=node("div","");grid.className="insights-grid";for(const [title,key,line]of [["Transaction activity · UTC dates","activity",true],["Risk distribution · scored entries","risk"],["Risk rules triggered","rules"],["Data-quality reasons","quality"],["Review outcomes","reviews"],["Activity by account · transaction count","accounts"],["Domestic / cross-border activity","cross_border"],["Batch outcomes · row counts","batch_outcomes"]])grid.append(chart(title,data[key],line));panel.append(grid,node("p",`Batch view: ${data.batch_reconciliation.batches} batches; ${data.batch_reconciliation.rows_received} received rows; ${data.batch_reconciliation.unknown_totals} unknown totals. ${data.batch_reconciliation.counts_consistent?"Reported batch counts reconcile.":"Reconciliation requires investigation."}`));if(data.batches_bounded||data.quarantine_bounded)panel.append(node("p","Quality and batch views are bounded to the latest 100 authorized cases/batches; use paginated details for older data."));byId("content").replaceChildren(panel);}
