function reviewFilters(meta){const tabs=node("div","");tabs.className="tabs";tabs.setAttribute("aria-label","Review ownership filters");for(const [label,value]of [["My reviews","mine"],["Unassigned","unassigned"],["All open","open"],["High risk","high"],["Over SLA","over_sla"]]){const b=button(label,()=>{reviewQueueFilter=value;offset=0;load();});b.setAttribute("aria-pressed",String(reviewQueueFilter===value));tabs.append(b);}byId("content").prepend(tabs);if(meta?.sla_configured===false)tabs.after(node("p","No review SLA is configured. No deadline has been assumed."));}
async function assignReview(row,assignee,notes="Claimed for investigation"){try{await request(`/v1/reviews/${row.risk_event_id}/assignment`,{method:"POST",body:JSON.stringify({request_id:crypto.randomUUID(),expected_version:row.version,assignee,notes})});notify("Review assignment saved and audited.","SUCCESS","Review Queue");await load();}catch(e){error(e);}}
async function assignmentEditor(row){try{const users=(await request("/v1/review-assignees")).data;const form=node("form","");form.id="review-assignment-form";form.append(node("h3","Assign review"));const label=node("label","Analyst");const select=node("select","");const unassigned=node("option","Unassigned");unassigned.value="";select.append(unassigned);for(const u of users){const o=node("option",`${u.display_name} (${u.username})`);o.value=u.username;select.append(o);}select.value=row.reviewer_subject||"";label.append(select);const reason=node("label","Assignment reason");const input=node("input","");input.required=true;input.maxLength=500;reason.append(input);const submit=node("button","Save assignment");submit.type="submit";form.append(label,reason,submit,button("Cancel",()=>load()));form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{await assignReview(row,select.value||null,input.value);}finally{submit.disabled=false;}};byId("content").replaceChildren(form);}catch(e){error(e);}}
